changeSet.sql:
DO $$
DECLARE
    seed_type RECORD;
    new_loc_id NUMERIC;
    new_type_id BIGINT;
BEGIN
    FOR seed_type IN
        SELECT * FROM (VALUES
            ('REAGENT', 10, 'Reagent', 'Réactif', 'Reagen'),
            ('RDT', 20, 'RDT (Rapid Diagnostic Test)', 'TDR (Test de diagnostic rapide)', 'RDT (Tes Diagnostik Cepat)'),
            ('CARTRIDGE', 30, 'Analyzer Cartridge', 'Cartouche d''analyseur', 'Kartrid Analisis'),
            ('HIV_KIT', 40, 'HIV Test Kit', 'Kit de test VIH', 'Kit Tes HIV'),
            ('SYPHILIS_KIT', 50, 'Syphilis Test Kit', 'Kit de test syphilis', 'Kit Tes Sifilis')
        ) AS t(code, sort_order, name_en, name_fr, name_id)
    LOOP
        SELECT nextval('clinlims.localization_seq') INTO new_loc_id;
        INSERT INTO clinlims.localization (id, description, lastupdated)
        VALUES (new_loc_id, 'inventory item type: ' || seed_type.code, now());

        INSERT INTO clinlims.localization_value (id, localization_id, locale, value, last_updated)
        VALUES (nextval('clinlims.localization_value_seq'), new_loc_id, 'en', seed_type.name_en, now());
        INSERT INTO clinlims.localization_value (id, localization_id, locale, value, last_updated)
        VALUES (nextval('clinlims.localization_value_seq'), new_loc_id, 'fr', seed_type.name_fr, now());
        INSERT INTO clinlims.localization_value (id, localization_id, locale, value, last_updated)
        VALUES (nextval('clinlims.localization_value_seq'), new_loc_id, 'id', seed_type.name_id, now());

        SELECT nextval('clinlims.inventory_item_type_seq') INTO new_type_id;
        INSERT INTO clinlims.inventory_item_type
            (id, code, name_localization_id, is_active, sort_order, is_seeded, lastupdated)
        VALUES
            (new_type_id, seed_type.code, new_loc_id, true, seed_type.sort_order, true, now());
    END LOOP;
END $$;

rollback.sql:
DELETE FROM clinlims.localization_value WHERE localization_id IN (
    SELECT name_localization_id FROM clinlims.inventory_item_type WHERE is_seeded = true
);
DELETE FROM clinlims.localization WHERE id IN (
    SELECT name_localization_id FROM clinlims.inventory_item_type WHERE is_seeded = true
);
DELETE FROM clinlims.inventory_item_type WHERE is_seeded = true;

ALTER TABLE clinlims.inventory_item
ADD CONSTRAINT chk_item_type
CHECK (item_type IN ('REAGENT', 'RDT', 'CARTRIDGE', 'HIV_KIT', 'SYPHILIS_KIT'));
